ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Inventario.DataContracts
---
soapenv#Envelope: {
    soapenv#Header: {},
    soapenv#Body: 
        tem#Consulta_Inventario: {
            tem#WSRequestHeader: {
            	tier#system: {
            		tier#correlationId: vars.inputData.correlationId,
            		tier#name: vars.inputData.name,
            		tier#processingServer: vars.inputData.processingServer
            	}
            },
            tem#parametros: {
                ws#id_servicio: vars.inputData.idServicio,
                ws#identificador_transaccion: vars.inputData.idTransaccion
            }
        }
         
}

%dw 2.0
output application/json
---
{
    System: {
        correlationID: vars.inputData.correlationId,
        processingServer: vars.inputData.processingServer,
        responseDate: now()
    },
    Response: {
        respuesta: "Error de consulta",
        codRespuesta: "404"
    }
}

%dw 2.0
output application/json
---
{
    System: {
        correlationID: vars.inputData.correlationId,
        processingServer: vars.inputData.processingServer,
        responseDate: now()
    },
    Response: {
        ResponseInventario: 
	        vars.result.*ResponseInventario map () -> {
                ID_Producto: $.ID_Producto,
                codigo_sap: $.codigo_sap,
                descripcion: $.descripcion,
                id_inventario: $.id_inventario,
                respuesta: $.respuesta,
                serial: $.serial
            }
    }
}
